function ItemView({ item }: { item: Item }): React.ReactElement {
  return (
    <Box flexDirection="column" marginBottom={item.kind === "tool" ? 0 : 1}>
      {item.kind === "banner" && <Banner />}
      {item.kind === "user" && (
        <Text>
          <Text color={theme.orange} bold>
            ❯{" "}
          </Text>
          <Text color={theme.dim}>{item.text}</Text>
        </Text>
      )}
      {item.kind === "assistant" && (
        <Box flexDirection="row">
          <Box width={2} flexShrink={0}>
            <Text color={theme.orange}>✦</Text>
          </Box>
          <Box flexDirection="column" flexGrow={1}>
            <Markdown text={item.text} />
          </Box>
        </Box>
      )}
      {item.kind === "tool" && (
        <Box flexDirection="column">
          <Text>
            <Text color={item.status === "ok" ? theme.green : theme.red}>
              {item.status === "ok" ? "  ⏺" : "  ⊘"}
            </Text>
            <Text color={theme.ink}> {item.tool}</Text>
            {item.hint ? <Text color={theme.dim}> {item.hint}</Text> : null}
          </Text>
          {item.text ? (
            <Box marginLeft={4} flexDirection="column">
              {item.text.split("\n").map((l, i) => (
                <Text key={i} color={theme.faint}>
                  {l}
                </Text>
              ))}
            </Box>
          ) : null}
        </Box>
      )}
      {item.kind === "notice" && (
        <Text color={theme.dim} italic>
          ◦ {item.text}
        </Text>
      )}
      {item.kind === "error" && <Text color={theme.red}>✗ {item.text}</Text>}
      {item.kind === "shell" && (
        <Box flexDirection="column" marginLeft={2}>
          {item.text.split("\n").slice(0, 20).map((l, i) => (
            <Text key={i} color={item.status === "error" ? theme.red : theme.faint}>
              {l}
            </Text>
          ))}
        </Box>
      )}
    </Box>
  );
}

